document.addEventListener("DOMContentLoaded", () => {
    const dropdowns = document.querySelectorAll(".dropdown");
    mltkLogger.debug(`dropdowns: ${dropdowns}`)
    
    dropdowns.forEach(drop => {
      drop.addEventListener("click", (event) => {
        event.stopPropagation(); // Prevent closing immediately
        closeAllDropdowns(drop); // Close others
        drop.classList.toggle("open");
      });
    });

    // Close dropdowns when clicking outside
    document.addEventListener("click", () => {
      closeAllDropdowns();
    });
});

function closeAllDropdowns(except = null) {
  document.querySelectorAll(".dropdown").forEach(drop => {
    if (drop !== except) {
        drop.classList.remove("open");
        mltkLogger.debug(`Closed dropdown named: ${drop.id}`)
    };
  });
}

function setupMenuBar() {
  document.getElementById("menuHome").addEventListener("click", () => showTab("home"));
  document.getElementById("menuLocale").addEventListener("click", () => showTab("locale"));
  document.getElementById("menuMerge").addEventListener("click", () => showTab("merge"));
  document.getElementById("menuDates").addEventListener("click", () => showTab("dates"));
  document.getElementById("menuNumbers").addEventListener("click", () => showTab("numbers"));
  document.getElementById("menuSettings").addEventListener("click", () => showTab("settings"));
  document.getElementById("menuHelp").addEventListener("click", () => showTab("help"));
  loadDefaultTab();
}

/* ---------------------------
   Menu SYSTEM
---------------------------- */

function showTab(tab) {
    document.querySelectorAll(".tab-panel").forEach(p => p.style.display = "none");  // Hide all panels
    document.getElementById("tab-" + tab).style.display = "block";  // Show selected panel
}

function loadDefaultTab() {
    showTab("home");
}

